import{_ as i,H as a,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"08-数据算法：因材施教，为你的系统选好老师","description":"","frontmatter":{},"headers":[{"level":2,"title":"用户特征","slug":"用户特征","link":"#用户特征","children":[{"level":3,"title":"数据管理平台（DMP）","slug":"数据管理平台-dmp","link":"#数据管理平台-dmp","children":[]},{"level":3,"title":"人群扩展算法（Look-alike）","slug":"人群扩展算法-look-alike","link":"#人群扩展算法-look-alike","children":[]}]},{"level":2,"title":"物品特征","slug":"物品特征","link":"#物品特征","children":[{"level":3,"title":"知识图谱（KG）","slug":"知识图谱-kg","link":"#知识图谱-kg","children":[]}]},{"level":2,"title":"场景特征","slug":"场景特征","link":"#场景特征","children":[{"level":3,"title":"实时特征","slug":"实时特征","link":"#实时特征","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]}],"relativePath":"AI大模型系统实战/08-数据算法：因材施教，为你的系统选好老师.md","filePath":"AI大模型系统实战/08-数据算法：因材施教，为你的系统选好老师.md","lastUpdated":1795452834000}'),p={name:"AI大模型系统实战/08-数据算法：因材施教，为你的系统选好老师.md"};function E(n,e,o,s,r,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="_08-数据算法-因材施教-为你的系统选好老师" tabindex="-1">08-数据算法：因材施教，为你的系统选好老师 <a class="header-anchor" href="#_08-数据算法-因材施教-为你的系统选好老师" aria-label="Permalink to &quot;08-数据算法：因材施教，为你的系统选好老师&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上节课我们学习了模型工程相关的知识，你掌握得如何？今天，我们来进一步学习更多的数据算法。</p><p>其实数据算法的本质是对人类智能的仿生，作为人类，我们进化出了神经反馈系统、大脑和各种感官。我们与生俱来的眼耳鼻舌身意这些高配传感器，还有大脑这个深度神经网络，让我们成为万物灵长，稍加学习就能适应外部世界。</p><p>不过作为 AI 系统造物主的你，就没那么轻松了。你需要先发挥自己的聪明才智，替 AI 系统去选择合适的输入数据，才能让你的 AI 系统足够智能。</p><p>你可能会问，为什么非得我们代劳，来完成选择数据的工作呢？我举个例子你就明白了。</p><p>假设，我们希望让一个智能体快速察觉到班主任的凝视，这个智能体很难自己判断哪些“数据”是重要的，它需要问遍身体的每一个传感器，才有可能找到传感信号和探测目标之间的关系。而我们只需要根据生活经验稍作思考，就知道最有价值的是听觉和视觉信号，只要将摄像头和麦克风信号供给模型，它就能判断是否有“危险”了。</p><p>在 AI 系统里也是同样的道理，我们利用人类的经验把数据分成了主体数据、客体数据和环境数据这三类数据。比如在无人驾驶和车联网系统中，这三类数据对应的是车辆数据、交通流数据和环境数据。</p><p>再比如我们熟悉的 AIRC 系统，它利用数据包括用户特征、物品特征和场景特征。这些数据都遵循了主体、客体和环境这种划分方式。</p><p>不过，给数据分类只是一小步。数据类别不同，学习方式和重点也各不相同，为了让 AI 系统早日成为学霸，我们还需要为它定制更合理的学习思路，说得更专业一些，就是根据不同任务的数据特点，选择最合适的数据建模方式。</p><h2 id="用户特征" tabindex="-1">用户特征 <a class="header-anchor" href="#用户特征" aria-label="Permalink to &quot;用户特征&quot;">​</a></h2><p>我们知道几乎所有商业公司，都会强调一条企业文化，那就是客户第一（ConsumerObsession），因为客户买账是商业模式延续下去的前提。所以一开始，我们先将注意力放在对用户特征的理解上，因为你所有的工作都是为了“投其所好”。</p><p>如果你不知道从何下手，你不妨和我刚才一样，从日常更容易观察到的线下场景来推演。</p><p>现在闭上眼睛（仅限听众），我们进入情景——假如你是某商场美妆区负责人，领导和你说，现在美妆区的客流量越来越少，你去发传单招揽一些客户回来。</p><p>于是，你拿着传单，站在商场门前的广场上，在川流不息的人群中风中凌乱。你发现每个人都在躲避你的眼神，所以，你意识到自己只能将传单发给有限的人，你该如何选择你的重点对象？</p><p>我猜你大概率会选年轻且爱打扮的女生，因为她才更有可能成为你产品的主要客户。现在睁开眼睛吧（仅限听众），我们回到线上的场景，你该如何发现这些对象呢？</p><p>答案是用户画像。用户画像数据被视为每个产品最宝贵的资源，同时也是 AI 系统中价值最高的数据。因此，AI 系统必须充分利用这些有限的数据资源，以提供更有价值的信息。</p><h3 id="数据管理平台-dmp" tabindex="-1">数据管理平台（DMP） <a class="header-anchor" href="#数据管理平台-dmp" aria-label="Permalink to &quot;数据管理平台（DMP）&quot;">​</a></h3><p>各大科技公司为了更充分地利用这些数据，一般采用专门的数据管理平台（DataManagement Platform，DMP）对用户特征进行管理，管理的数据包括三类。</p><ol><li><p>第一方数据，用户使用产品时产生的信息，其中包括用户个人注册信息，人群特征数据等等。</p></li><li><p>第二方数据，是团队内部产品或者业务伙伴提供的数据。</p></li><li><p>第三方数据，数据供应商提供的数据，例如从 BlueKai、秒针这类地方购买的数据。</p></li></ol><p>DMP 中会将用户基本信息（例如性别、年龄、职业），使用习惯和行为记录（例如点击、购买、收藏）等信息综合起来，生成用户画像。这看似是一个简单过程，其实蕴藏了很多技术难题。为了应对这些难题，我们的系统需要建设后面这两种能力。</p><ul><li><p>第一种是对数据做“身份对齐”的能力，比如对同一人在多设备、多账号产生的数据做身份识别。</p></li><li><p>第二种则是挖掘某个人群的“潜在用户”的能力，比如识别符合某个品牌产品调性的用户。</p></li></ul><p>不要小瞧这两个能力，它们不仅能够大幅提高数据质量，提升你的模型效果。还是你系统的“印钞机”，可以大幅提高 AI 系统的营销收入。</p><p>这里提一句题外话，营销能力不仅是 AIRC 系统商业逻辑得以延续的必要条件，也是 AIGC 系统的必由之路。</p><h3 id="人群扩展算法-look-alike" tabindex="-1">人群扩展算法（Look-alike） <a class="header-anchor" href="#人群扩展算法-look-alike" aria-label="Permalink to &quot;人群扩展算法（Look-alike）&quot;">​</a></h3><p>为了具备这两个能力，AI 系统中的一个重要武器 Lookalike 就派上用场了。它有三大作用。</p><ol><li><p>挖掘潜在高净值用户。比如识别出与“保时捷”车主相似的用户，扩大推广活动的覆盖范围。</p></li><li><p>提高风控能力。比如通过用户相似行为和特征，发现黑灰产作案团伙，识别出潜在欺诈活动。</p></li><li><p>提高冷启动推荐效果。比如利用相似人的特征代表未知新用户，做出更准确的推荐决策。</p></li></ol><p>实现 Lookalike，完全可以用上节课你所学到的 DeepWalk 算法。但是这节课我们来学习一个新的算法，也就是上节课预告的 GraphSAGE，当时我们提过，和两阶段的 DeepWalk 算法相比，GraphSAGE 是一个端到端的方案，能更好地保留图结构中的信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/1.png" alt=""></a></p><p>我们对照前面的图解，来梳理一下 GraphSAGE 的具体细节。</p><ol><li><p>建图：将用户作为节点，如果用户之间若存在相同属性，则增加一条边。</p></li><li><p>采集：随机选一个幸运节点，向它的各个方向走两步，路径会形成一棵树，如左图。你需要重复此过程，采出若干棵树，留作备用。</p></li><li><p>聚合：随机取一棵树，将第三层节点和向第二层聚合（如中图），生成第二层节点表征。之后再对第二层和树根做同样的操作，每棵树都如法炮制。</p></li><li><p>训练：将树根原来的表征与上一步的聚合表征拼接起来，以此来保留图中结构信息（如右图），然后与一个参数相乘，就得到了树根的融合表征。</p></li></ol><p>这里先简单提一下，这些步骤背后的思想其实和大模型技术 Transformer 中的位置编码很像，到时候我会再和你详细讲解。这里我们回到 GraphSage 算法。</p><p>因为每个节点都有可能成为树根，所以每个节点都能获取自己的融合表征。算法训练的过程，其实就是在调整第四步中那个参数，使得每个人对应节点的融合表征在高维空间中的距离，和真实世界中的距离尽量一致。本质上就是让这个参数来表达高维空间映射的投影规则。</p><p>完成这些步骤之后，Lookalike 的最后一步就很简单了，只要将高维空间中与高净值用户距离最接近的那群人作为潜在用户就好了。其实多设备、多场景的身份对齐也是同样的道理，我们只要找到足够相近的两个人，将他们近似识别成同一人就可以（真实场景用法更复杂些，不过是同样的道理）。</p><p>当然这其中有一个鸭子测试的假设，那就是如果它看起来像鸭子、走路像鸭子、叫声像鸭子，它就是鸭子。这里我为你准备了一张示意图，你可以点开文稿去看看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/2.png" alt=""></a></p><h2 id="物品特征" tabindex="-1">物品特征 <a class="header-anchor" href="#物品特征" aria-label="Permalink to &quot;物品特征&quot;">​</a></h2><p>解决了用户特征的问题，接下来学习物品特征的处理方法。物品是 AI 系统商业目标的载体，它几乎与系统中的所有实体都有交互，可以建立丰富的连接。而这恰恰是知识图谱最喜欢的，所以 AI 系统往往会围绕物品的“朋友圈”来构建知识图谱。</p><h3 id="知识图谱-kg" tabindex="-1">知识图谱（KG） <a class="header-anchor" href="#知识图谱-kg" aria-label="Permalink to &quot;知识图谱（KG）&quot;">​</a></h3><p>知识图谱起源于上节课三大派别中的符号主义派，是一种用于表示和组织知识的图形结构，由多个“实体 - 关系 - 实体”的三元组所组成。</p><p>相较于其他图结构，知识图谱的边上携带了更丰富的信息。它不仅在 AIRC 系统中发挥了重要的作用，同样也是 AIGC 系统中，提示语工程的重要组成部分。</p><p>今天我们重点关注构建知识图谱的三个主要步骤：知识抽取、知识融合和知识加工。因为这三个步骤是知识图谱技术的核心特征，值得我们多花时间先搞清楚。</p><p>至于在每个步骤中所涉及的算法则纷繁复杂，相对而言，并不是那么重要。你已经学习的各种算法几乎都可以应用于知识图谱的构建过程中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/3.png" alt=""></a></p><p>首先是知识抽取，这是“拿知识”的过程。目标是从文本、网页、数据库等不同的地方提取数据，识别并提取出实体、属性和它们之间的关系，以便构建知识图谱。拿知识的技术包括识别实体、提取关系和属性等。</p><p>然后是知识融合，这是“合知识”的过程。目标是解决数据不一致和冲突的问题，将来自不同数据源的知识进行统一和一致化，从而生成更准确和完整的知识图谱。合知识的技术包括对齐实体、对齐关系和解决冲突等。</p><p>最后是知识加工，这是“学知识”的过程。目标是使知识图谱更可用和可靠，方便后续的知识检索、推理和应用。学知识的技术包括清洗数据、补充数据和进行知识推理等。</p><p>清楚了各个步骤的定位之后，我再带你学习一个知识图谱应用的例子，帮你建立一些直观的认识。在 AIRC 系统中，我们常常利用知识图谱来对物品、相关信息和用户之间的关系进行建模，从而获取“物品地图”中的各个兴趣点（Point of Interest，POI），挖掘用户各个兴趣中潜在的关联内容。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/4.png" alt=""></a></p><p>如上图，如果某个用户对美白感兴趣，你可以基于 POI 实时收集相关的物料，通过组合它们来自动形成下图相应的商品创意。这种方法往往可以生成更符合用户喜好的产品介绍，更好地挖掘用户的需求，获得更高的点击率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/08-%25E6%2595%25B0%25E6%258D%25AE%25E7%25AE%2597%25E6%25B3%2595/5.png" alt=""></a></p><ul><li>生成的产品使用前后对比图</li></ul><h2 id="场景特征" tabindex="-1">场景特征 <a class="header-anchor" href="#场景特征" aria-label="Permalink to &quot;场景特征&quot;">​</a></h2><p>最后，让我们来看一下场景特征的特征。场景特征来自于每一次流量请求中客户端提供的信息，被用于刻画用户触达应用时的全景信息，包括后面这些信息。</p><ul><li><p>应用程序所处的界面（应用、页面、媒体位等）</p></li><li><p>用户的设备信息（信号强度、手机型号、电池电量等）</p></li><li><p>所在地点信息（城市、气温、邮编等）</p></li><li><p>…</p></li></ul><p>在处理场景特征时，我们需要将与用户长期习惯相关的数据放在用户画像中。那些随着场景变化频率较高的数据应该放在场景特征中。</p><h3 id="实时特征" tabindex="-1">实时特征 <a class="header-anchor" href="#实时特征" aria-label="Permalink to &quot;实时特征&quot;">​</a></h3><p>我想进一步说明的是，场景特征的最大价值，在于它在时间维度上的区分性和敏感性。例如“用户最近 30 分钟的商品点击数量”或“用户最近 1 小时浏览商品数量”这些实时特征都是非常重要的，它们会对推荐结果产生很大影响。为什么这么说呢？</p><p>这是因为用户画像和物料特征数据相对稳定，更新频率不高，如果不增加场景特征，模型的输入值很可能在一段时间内没有任何变化。因此，场景特征的输入可以让模型变得更加敏感。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天的学习到这里告一段落，我们做一个回顾。</p><p>在这节课上，我们学习了如何根据具体的业务场景选择适合 AI 系统的数据。具体内容包括这三个方面。</p><ol><li><p>用户画像的构成，以及相似人群扩展的技术。</p></li><li><p>物品特征的构成，知识图谱技术的关键步骤。</p></li><li><p>场景特征的定位，以及实时特征的独特价值。</p></li></ol><p>除此之外，我还是想提醒你，对生活的观察和体验是数据智能工作中很重要的一个部分，只有长时间和数据“泡在一起”，才能更深入地理解用户使用系统的习惯，清楚知道我们有哪些能利用的原材料，得到最符合直觉的重要特征。</p><p>更值得一提的是，这节课讲到的图神经网络、知识图谱和跨模态预训练模型技术都是 AI 大模型系统最重要的前序知识，一定要熟练掌握。</p><p>在下节课中，我会带你结合这一章的全部知识，构建完整的 AI 系统，敬请期待！</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>为了更好地巩固今天所学内容，请你尝试回答后面的问题。</p><p>你认为 ChatGPT 中的主体、客体和环境数据分别是什么？如何基于用户、内容和场景的特征来优化 ChatGPT 的内容生成质量？答出大概思路即可。</p><p>如何区分场景特征和用户特征，比如“用户最近 30 分钟内，观看的运动类视频数量”是哪类特征？</p><p>如果让你选择三个算法，放入知识图谱的三个步骤中，你会选哪三个？</p><p>恭喜你完成我们第 8 次打卡学习，期待你在留言区和我交流互动。也欢迎你把这节课分享给身边朋友，和 TA 一起学习进步。</p>',72)])])}const u=i(p,[["render",E]]);export{B as __pageData,u as default};
